-- READ ONLY: schema/security metadata only; no application, vault or cron rows.
SELECT jsonb_build_object(
 'extensionOwnedRelations',(SELECT coalesce(jsonb_agg(jsonb_build_object('identity',format('%I.%I',n.nspname,c.relname),'extension',e.extname) ORDER BY n.nspname,c.relname),'[]'::jsonb) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_type t ON t.typrelid=c.oid JOIN pg_depend d ON d.classid='pg_type'::regclass AND d.objid=t.oid AND d.deptype='e' JOIN pg_extension e ON e.oid=d.refobjid WHERE c.relkind='c' AND n.nspname IN ('public','private','flow_private','pto_private','sales_credit_private','time_private','work_order_private','jobs')),
 'sequenceOwnership',(SELECT coalesce(jsonb_agg(jsonb_build_object('sequence',format('%I.%I',ns.nspname,s.relname),'table',format('%I.%I',nt.nspname,t.relname),'column',a.attname,'dependencyKind',d.deptype) ORDER BY ns.nspname,s.relname),'[]'::jsonb) FROM pg_class s JOIN pg_namespace ns ON ns.oid=s.relnamespace JOIN pg_depend d ON d.classid='pg_class'::regclass AND d.objid=s.oid AND d.refclassid='pg_class'::regclass AND d.deptype IN ('a','i') JOIN pg_class t ON t.oid=d.refobjid JOIN pg_namespace nt ON nt.oid=t.relnamespace JOIN pg_attribute a ON a.attrelid=t.oid AND a.attnum=d.refobjsubid WHERE s.relkind='S' AND ns.nspname IN ('public','private','flow_private','pto_private','sales_credit_private','time_private','work_order_private','jobs')),
 'roleAttributes',(SELECT jsonb_agg(jsonb_build_object('name',rolname,'superuser',rolsuper,'inherit',rolinherit,'bypassRls',rolbypassrls,'canLogin',rolcanlogin) ORDER BY rolname) FROM pg_roles),
 'roleMemberships',(SELECT jsonb_agg(jsonb_build_object('role',pg_get_userbyid(roleid),'member',pg_get_userbyid(member),'adminOption',admin_option) ORDER BY roleid,member) FROM pg_auth_members),
 'publications',(SELECT jsonb_agg(jsonb_build_object('name',pubname,'allTables',puballtables,'insert',pubinsert,'update',pubupdate,'delete',pubdelete,'truncate',pubtruncate) ORDER BY pubname) FROM pg_publication),
 'publicationTables',(SELECT jsonb_agg(jsonb_build_object('publication',p.pubname,'table',format('%I.%I',n.nspname,c.relname)) ORDER BY p.pubname,n.nspname,c.relname) FROM pg_publication_rel r JOIN pg_publication p ON p.oid=r.prpubid JOIN pg_class c ON c.oid=r.prrelid JOIN pg_namespace n ON n.oid=c.relnamespace),
 'unsupportedCustomKinds',(SELECT jsonb_build_object(
 'aggregates',(SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('public','private','flow_private','pto_private','sales_credit_private','time_private','work_order_private','jobs') AND p.prokind IN ('a','w') AND NOT EXISTS(SELECT 1 FROM pg_depend d WHERE d.classid='pg_proc'::regclass AND d.objid=p.oid AND d.deptype='e')),
 'collations',(SELECT count(*) FROM pg_collation c JOIN pg_namespace n ON n.oid=c.collnamespace WHERE n.nspname IN ('public','private') AND NOT EXISTS(SELECT 1 FROM pg_depend d WHERE d.classid='pg_collation'::regclass AND d.objid=c.oid AND d.deptype='e')),
 'operators',(SELECT count(*) FROM pg_operator o JOIN pg_namespace n ON n.oid=o.oprnamespace WHERE n.nspname IN ('public','private') AND NOT EXISTS(SELECT 1 FROM pg_depend d WHERE d.classid='pg_operator'::regclass AND d.objid=o.oid AND d.deptype='e'))))
) AS metadata;
